import{_ as a,a as t,o,ai as r}from"./chunks/framework.BbOtTPsL.js";const g=JSON.parse('{"title":"CMS Pages","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/cms/pages/index.md","filePath":"api/graphql-api/admin/cms/pages/index.md","lastUpdated":1781099665000}'),s={name:"api/graphql-api/admin/cms/pages/index.md"};function d(n,e,i,c,l,p){return o(),t("div",null,e[0]||(e[0]=[r('<h1 id="cms-pages" tabindex="-1">CMS Pages <a class="header-anchor" href="#cms-pages" aria-label="Permalink to &quot;CMS Pages&quot;">​</a></h1><p>CMS Pages are <strong>static storefront content pages</strong> — About Us, Privacy Policy, custom landing pages, and the like. Each page is served on the storefront at its <code>urlKey</code> (e.g. <code>/page/about-us</code>). This menu mirrors the admin <strong>CMS → Pages</strong> screen: list, create, edit, delete, and view those pages.</p><h2 id="multi-locale-multi-channel" tabindex="-1">Multi-locale, multi-channel <a class="header-anchor" href="#multi-locale-multi-channel" aria-label="Permalink to &quot;Multi-locale, multi-channel&quot;">​</a></h2><p>A page is content that spans languages and storefronts:</p><ul><li><strong>Multi-locale</strong> — a page holds <strong>one content set per language</strong> (its <code>translations</code>). Each locale has its own <code>pageTitle</code>, <code>htmlContent</code>, <code>urlKey</code>, and SEO fields. Over GraphQL, <code>translations</code> is a <strong>field-selectable connection</strong> — query it via <code>translations { edges { node { … } } }</code>, picking from <code>locale</code>, <code>pageTitle</code>, <code>urlKey</code>, <code>htmlContent</code>, <code>metaTitle</code>, <code>metaKeywords</code>, <code>metaDescription</code>. It returns one entry per authored locale on both the listing and the detail query. (Over REST it comes back as a plain JSON array.)</li><li><strong>Multi-channel</strong> — a page is <strong>assigned to one or more channels</strong> (storefronts). Over GraphQL, <code>channels</code> is also a <strong>field-selectable connection</strong> — query it via <code>channels { edges { node { … } } }</code>, picking from <code>id</code>, <code>code</code>, <code>name</code>. (Over REST it comes back as a plain JSON array.)</li></ul><h2 id="previewurl-—-the-view-action" tabindex="-1"><code>previewUrl</code> — the &quot;View&quot; action <a class="header-anchor" href="#previewurl-—-the-view-action" aria-label="Permalink to &quot;`previewUrl` — the &quot;View&quot; action&quot;">​</a></h2><p>Every node carries a <code>previewUrl</code> — the storefront URL where the page actually renders (built from its <code>urlKey</code>). This is the API equivalent of the admin <strong>View</strong> action: open it in a browser to preview the live page.</p><h2 id="all-multi-word-fields-resolve-over-graphql" tabindex="-1">All multi-word fields resolve over GraphQL <a class="header-anchor" href="#all-multi-word-fields-resolve-over-graphql" aria-label="Permalink to &quot;All multi-word fields resolve over GraphQL&quot;">​</a></h2><p><code>pageTitle</code>, <code>urlKey</code>, <code>metaTitle</code>, <code>metaKeywords</code>, <code>metaDescription</code>, <code>layout</code>, <code>previewUrl</code>, <code>htmlContent</code>, and the timestamps all <strong>resolve over GraphQL</strong> on both the listing and the detail query — none come back <code>null</code> for transport reasons. <code>translations</code> and <code>channels</code> are <strong>field-selectable connections</strong> (<code>translations { edges { node { … } } }</code> / <code>channels { edges { node { … } } }</code>) on both queries.</p><p>The node <code>id</code> is the IRI <code>/api/admin/cms/pages/{id}</code>; <code>_id</code> is the numeric ID. The single-page query takes that IRI as its <code>id: ID!</code> argument.</p><h2 id="create-vs-update-payload-shapes" tabindex="-1">Create vs Update payload shapes <a class="header-anchor" href="#create-vs-update-payload-shapes" aria-label="Permalink to &quot;Create vs Update payload shapes&quot;">​</a></h2><p>The two write mutations take <strong>different shapes</strong> (this mirrors the admin form):</p><ul><li><strong>Create</strong> sends <strong>top-level</strong> fields (<code>urlKey</code>, <code>pageTitle</code>, <code>htmlContent</code>, <code>meta*</code>, <code>channels</code>). Those values are <strong>broadcast to every configured locale</strong> at creation.</li><li><strong>Update</strong> sends a <strong>locale-nested</strong> body so you edit one locale at a time.</li></ul><h2 id="graphql-vs-rest" tabindex="-1">GraphQL vs REST <a class="header-anchor" href="#graphql-vs-rest" aria-label="Permalink to &quot;GraphQL vs REST&quot;">​</a></h2><p>Both transports expose the same data and behaviour. The practical difference: GraphQL lets you fetch the page <strong>plus</strong> its <code>translations</code> and <code>channels</code> in a <strong>single round trip</strong> and pick exactly the fields you need, whereas REST returns the full fixed payload per endpoint.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/cms/pages/queries/list.html">List pages</a></td><td><code>adminCmsPages</code> query (cursor)</td></tr><tr><td><a href="/api/graphql-api/admin/cms/pages/queries/detail.html">Page detail</a></td><td><code>adminCmsPage(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/cms/pages/mutations/create.html">Create page</a></td><td><code>createAdminCmsPage</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/cms/pages/mutations/update.html">Update page</a></td><td><code>updateAdminCmsPage</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/cms/pages/mutations/delete.html">Delete page</a></td><td><code>deleteAdminCmsPage</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/cms/pages/mutations/mass-delete.html">Mass delete pages</a></td><td><code>createAdminCmsPageMassDelete</code> mutation</td></tr><tr><td>Export pages (CSV)</td><td><strong>REST only</strong> — see <a href="/api/rest-api/admin/cms/pages/export.html">Export CMS Pages</a>.</td></tr></tbody></table><p>All CMS Pages operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>. Writes require the matching <code>cms.create</code> / <code>cms.edit</code> / <code>cms.delete</code> permission.</p>',18)]))}const m=a(s,[["render",d]]);export{g as __pageData,m as default};
